def _raises_code(call):
    try:
        call()
    except Exception as error:
        return type(error).__name__
    return ''


def _p01(i):
    stage, reason, shape, _switch, _attempt, _klass = _row(i)
    return _raises_code(lambda: _vwf(_pair(stage, reason, shape))) == ''


